package password

import (
	"errors"

	"golang.org/x/crypto/bcrypt"
)

var ErrMismatch = errors.New("password: hash and password do not match")

func Hash(plain string) (string, error) {
	h, err := bcrypt.GenerateFromPassword([]byte(plain), bcrypt.DefaultCost)
	if err != nil {
		return "", err
	}
	return string(h), nil
}

func Verify(hash, plain string) error {
	if err := bcrypt.CompareHashAndPassword([]byte(hash), []byte(plain)); err != nil {
		return ErrMismatch
	}
	return nil
}

package password

import "testing"

func TestHashVerify(t *testing.T) {
	hash, err := Hash("s3cr3t")
	if err != nil {
		t.Fatalf("Hash: %v", err)
	}
	if hash == "s3cr3t" {
		t.Fatal("hash must not equal plaintext")
	}
	if err := Verify(hash, "s3cr3t"); err != nil {
		t.Fatalf("Verify correct password: %v", err)
	}
	if err := Verify(hash, "wrong"); err != ErrMismatch {
		t.Fatalf("Verify wrong password = %v, want ErrMismatch", err)
	}
}
